"В городах воду очищают на водоочистных станциях и по трубам подают в дома.": "Дар шаҳрҳо обро дар истгоҳҳои обтозакунӣ тоза мекунанд ва тавассути қубурҳо ба хонаҳо мерасонанд.",
"В грудной клетке — сердце и лёгкие, в брюшной полости — желудок, кишечник, печень и почки.": "Дар қафаси сина — дил ва шуш, дар ковоки шикам — меъда, рӯда, ҷигар ва гурдаҳо.",
"В желудке пища перемешивается и перерабатывается желудочным соком.": "Дар меъда ғизо омехта мешавад ва бо шираи меъда коркард мешавад.",
