"В зелёных листьях на свету вода и углекислый газ превращаются в питательные вещества. Это называется фотосинтез.": "Дар баргҳои сабз дар рӯшноӣ об ва гази карбон ба моддаҳои ғизоӣ табдил меёбанд. Ин фотосинтез номида мешавад.",
