"В листьях есть крошечные отверстия — устьица. Через них растение дышит и испаряет воду.": "Дар баргҳо сӯрохиҳои хурд ҳастанд — рӯзанаҳо. Растанӣ тавассути онҳо нафас мекашад ва об бухор мекунад.",
"В лёгких происходит обмен газов": "Дар шуш мубодилаи газҳо рух медиҳад",
