"Источники электрической энергии — батарейка, аккумулятор, генератор, солнечная батарея. Электростанции вырабатывают ток для городов.": "Манбаҳои энергияи электрикӣ — батарея, аккумулятор, генератор, батареяи офтобӣ. Неругоҳҳои барқ ҷараёнро барои шаҳрҳо истеҳсол мекунанд.",
"Источники электричества": "Манбаҳои барқ",
